package cn.safetyledger.app;
import android.app.*;import android.os.Bundle;import android.view.*;import android.widget.*;import cn.safetyledger.app.data.Entities.*;import cn.safetyledger.app.data.LedgerRepository;import cn.safetyledger.app.media.MediaService;import cn.safetyledger.app.security.PasswordHash;
public final class TrashActivity extends Activity{private LedgerRepository repo;private LinearLayout list;@Override protected void onCreate(Bundle b){super.onCreate(b);repo=new LedgerRepository(this);LinearLayout root=Ui.column(this);LinearLayout bar=Ui.row(this);bar.setBackgroundColor(Ui.DARK);TextView back=Ui.text(this,"‹",34,true);back.setTextColor(0xffffffff);back.setOnClickListener(v->finish());TextView t=Ui.text(this,"回收站",21,true);t.setTextColor(0xffffffff);bar.addView(back,new LinearLayout.LayoutParams(Ui.dp(this,52),Ui.dp(this,56)));bar.addView(t,Ui.weight(1));root.addView(bar);ScrollView s=new ScrollView(this);list=Ui.column(this);list.setPadding(Ui.dp(this,10),Ui.dp(this,10),Ui.dp(this,10),Ui.dp(this,20));s.addView(list);root.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);load();}private void load(){list.removeAllViews();for(Inspection x:repo.list(null,null,null,true,1,100000).rows){LinearLayout box=Ui.column(this);box.setBackground(Ui.border(this,0xffcbd5e1));box.addView(Ui.text(this,x.date+" · "+x.templateName+"\n"+x.location,17,false));LinearLayout a=Ui.row(this);Button restore=Ui.button(this,"恢复"),delete=Ui.button(this,"永久删除");restore.setOnClickListener(v->{repo.restore(x.id);load();});delete.setOnClickListener(v->confirm(x));a.addView(restore,Ui.weight(1));a.addView(delete,Ui.weight(1));box.addView(a);list.addView(box);list.addView(Ui.gap(this,8));}}private void confirm(Inspection x){String hash=repo.setting("delete_password_hash","");if(hash.isBlank()){Ui.toast(this,"请先在设置中设置永久删除密码");return;}EditText p=Ui.input(this,"永久删除密码");p.setInputType(0x81);new AlertDialog.Builder(this).setTitle("不可恢复的永久删除").setMessage("将删除数据库记录和对应本地媒体，并建立 tombstone。此操作不可撤销。").setView(p).setPositiveButton("永久删除",(d,w)->{try{if(!PasswordHash.verify(p.getText().toString().toCharArray(),hash)){Ui.toast(this,"密码错误");return;}new MediaService(this).deleteInspectionMedia(x.id);repo.permanentDelete(x.id);Ui.toast(this,"已永久删除并建立 tombstone");load();}catch(Exception e){Ui.toast(this,"删除失败："+e.getMessage());}}).setNegativeButton("取消",null).show();}}
